def question(i,d,p,correct,wrong,why,source,hint):
    options=[correct]+[x[0] for x in wrong]; reasons=[why]+[x[1] for x in wrong]
    # Rotate authored answers so position is not a clue. Runtime also randomizes choices.
    n=i%len(options); options=options[n:]+options[:n]; reasons=reasons[n:]+reasons[:n]
    return dict(id=i,domain=d,q=p,kind='single',options=options,answer=(-n)%len(options),why=why,reasons=reasons,hint=hint,analysis=why,trap='Choose for the stated constraint, rather than a familiar service name.',clues=[],keyPoints=[],source=source,reviewedOn='2026-11-18',reviewStatus='Original source-aligned draft; independent expert review pending',contentRevision=1)
ml=[]
